using WypozyczalniaSportowa.Data;
using WypozyczalniaSportowa.Domain;
using WypozyczalniaSportowa.Domain.Contracts;
using WypozyczalniaSportowa.Domain.Exceptions;
using WypozyczalniaSportowa.Domain.Pricing;
namespace WypozyczalniaSportowa.Application;

public sealed class RentalApplicationService(IStoreRepository repository)
{
    private readonly Dictionary<int, Customer> _customers = []; private readonly List<Rental> _rentals = []; private readonly Queue<ServiceOrder> _serviceQueue = []; private readonly List<ServiceOrder> _serviceHistory = []; private readonly HashSet<int> _activeRentals = []; public Inventory<Equipment> Inventory { get; } = new(); public event EventHandler<RentalCreatedEventArgs>? RentalCreated; public IReadOnlyCollection<Customer> Customers => _customers.Values; public IReadOnlyList<Rental> Rentals => _rentals; public IReadOnlyCollection<ServiceOrder> ServiceHistory => _serviceHistory;
    public void Initialize() { var data = repository.Load(); if (data.Equipment.Count == 0 && data.Customers.Count == 0) { Seed(); Save(); return; } foreach (var x in data.Equipment) Inventory.Add(EquipmentFactory.Restore(x.Id, x.Kind, x.Name, x.DailyRate, x.IsAvailable, x.NeedsService, x.Detail)); foreach (var x in data.Customers) _customers.Add(x.Id, new Customer(x.Id, x.FullName, x.Email)); foreach (var x in data.Rentals) { var r = new Rental(x.Id, _customers[x.CustomerId], new RentalPeriod(x.Start, x.End)); foreach (var line in x.Lines) r.AddLine(Inventory.Find(line.EquipmentId), line.ChargedPrice); r.SetFinalTotal(x.Total); r.RestoreStatus(x.Status); _rentals.Add(r); if (r.Status == RentalStatus.Active) _activeRentals.Add(r.Id); } foreach (var x in data.ServiceOrders) { var order = new ServiceOrder(x.Id, x.EquipmentId, x.Description, x.IsCompleted); _serviceHistory.Add(order); if (!order.IsCompleted) _serviceQueue.Enqueue(order); } }
    private void Seed() { Inventory.Add(EquipmentFactory.Create("rower", "Rower trekkingowy", 65m, 21)); Inventory.Add(EquipmentFactory.Create("kajak", "Kajak dwuosobowy", 90m, 2)); Inventory.Add(EquipmentFactory.Create("namiot", "Namiot rodzinny", 50m, 4)); var c = new Customer("Jan Kowalski", "jan.kowalski@example.com"); _customers.Add(c.Id, c); }
    public Customer AddCustomer(string name, string email) { var c = new Customer(name, email); if (_customers.Values.Any(x => x.Email.Equals(c.Email, StringComparison.OrdinalIgnoreCase))) throw new DomainValidationException("Klient o tym e-mailu już istnieje."); _customers.Add(c.Id, c); Save(); return c; }
    public Equipment AddEquipment(string kind, string name, decimal rate, int detail) { var x = EquipmentFactory.Create(kind, name, rate, detail); Inventory.Add(x); Save(); return x; }
    public Rental CreateRental(int customerId, IEnumerable<int> ids, RentalPeriod period, IPricingStrategy strategy, decimal discount) { if (!_customers.TryGetValue(customerId, out var customer)) throw new CustomerNotFoundException(customerId); var selected = ids.Select(Inventory.Find).DistinctBy(x => x.Id).ToList(); if (selected.Count == 0) throw new DomainValidationException("Wybierz sprzęt."); foreach (var x in selected) { if (!x.IsAvailable) throw new EquipmentUnavailableException(x.Id); if (x is IServiceable s && s.NeedsService) throw new EquipmentUnavailableException(x.Id); } var rental = new Rental(customer, period); foreach (var x in selected) { Equipment baseItem = x; if (baseItem is Bicycle bike) _ = bike.Gears; var kayak = baseItem as Kayak; if (kayak is not null) _ = kayak.Seats; rental.AddLine(baseItem, baseItem.CalculateRentalPrice(period, strategy)); } var total = rental.Total; ApplyDiscount(ref total, discount); rental.SetFinalTotal(total); foreach (var x in selected) x.Reserve(); _rentals.Add(rental); _activeRentals.Add(rental.Id); try { Save(); } catch { foreach (var x in selected) x.Release(); _rentals.Remove(rental); _activeRentals.Remove(rental.Id); throw; } RentalCreated?.Invoke(this, new RentalCreatedEventArgs(ToReceipt(rental))); return rental; }
    public Rental ReturnRental(int id) { var r = _rentals.FirstOrDefault(x => x.Id == id) ?? throw new DomainValidationException($"Brak rezerwacji #{id}."); r.MarkReturned(); _activeRentals.Remove(id); foreach (var l in r.Lines) l.Equipment.Release(); Save(); return r; }
    public ServiceOrder ScheduleService(int id, string description) { var equipment = Inventory.Find(id); if (equipment is not IServiceable s) throw new DomainValidationException("Tego sprzętu nie można serwisować."); if (_activeRentals.Any(rid => _rentals.First(r => r.Id == rid).Lines.Any(l => l.Equipment.Id == id))) throw new EquipmentUnavailableException(id); if (s.NeedsService) throw new DomainValidationException("Sprzęt ma już otwarte zlecenie."); s.MarkForService(); var order = new ServiceOrder(id, description); _serviceQueue.Enqueue(order); _serviceHistory.Add(order); Save(); return order; }
    public ServiceOrder? CompleteNextService() { if (!_serviceQueue.TryDequeue(out var order)) return null; order.Complete(); if (Inventory.Find(order.EquipmentId) is IServiceable s) s.CompleteService(); Save(); return order; }
    public IEnumerable<Equipment> SortEquipment(IPricingStrategy strategy) => Inventory.OrderBy(x => x.CalculateRentalPrice(new RentalPeriod(DateOnly.FromDateTime(DateTime.Today), 1), strategy));
    public bool TryFindEquipment(int id, out Equipment? item) { try { item = Inventory.Find(id); return true; } catch (KeyNotFoundException) { item = null; return false; } }
    public static bool SameReference(Equipment first, Equipment second) => ReferenceEquals(first, second);
    public static void ApplyDiscount(ref decimal total, decimal rate) { if (rate is < 0 or > .50m) throw new DomainValidationException("Rabat może wynosić 0-50%."); total = decimal.Round(total * (1 - rate), 2, MidpointRounding.AwayFromZero); }
    public RentalReceipt ToReceipt(Rental r) => new(r.Id, r.Customer.FullName, r.Period.ToString(), r.Total, r.Status.ToString());
    public void Save() { var snapshot = new StoreSnapshot(Inventory.Select(x => new EquipmentSnapshot(x.Id, x.Kind, x.Name, x.DailyRate, x.IsAvailable, x is IServiceable s && s.NeedsService, x.Detail)).ToList(), _customers.Values.Select(x => new CustomerSnapshot(x.Id, x.FullName, x.Email)).ToList(), _rentals.Select(x => new RentalSnapshot(x.Id, x.Customer.Id, x.Period.Start, x.Period.End, x.Status, x.Total, x.Lines.Select(l => new RentalLineSnapshot(l.Equipment.Id, l.ChargedPrice)).ToList())).ToList(), _serviceHistory.Select(x => new ServiceOrderSnapshot(x.Id, x.EquipmentId, x.Description, x.IsCompleted)).ToList()); repository.Save(snapshot); }
    public override string ToString() => $"Wypożyczalnia: {Inventory.Count} sprzętów, {_customers.Count} klientów";
}
